class Rectangle {
  constructor(width, height) {
    this.width = width;
    this.height = height;
  }

  get area() {
    return this.width * this.height;
  }
}

const box = new Rectangle(2, 3);
box.width = 5;

console.log(box.area);
console.log(Object.keys(box).join(","));
console.log(JSON.stringify(box));
console.log("area" in box);
console.log(Object.hasOwn(box, "area"));
